 async function signIn(e){e.preventDefault();setBusy(true);setError('');const{error:err}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(err)setError(err.message);setBusy(false)}
 async function requestPasswordReset(){if(!email.trim()){setError('Enter your email first.');return;}setBusy(true);setError('');const{error:err}=await supabase.auth.resetPasswordForEmail(email.trim(),{redirectTo:window.location.origin+window.location.pathname});if(err)setError(err.message);else setResetEmailSent(true);setBusy(false)}
 async function saveNewPassword(e){e.preventDefault();setError('');if(newPassword.length<12){setError('Use at least 12 characters.');return;}if(newPassword!==confirmPassword){setError('Passwords do not match.');return;}if(!session){setError('Recovery link invalid or expired. Request a new one.');return;}setBusy(true);const{error:err}=await supabase.auth.updateUser({password:newPassword});if(err)setError(err.message);else{setRecovery(false);setNewPassword('');setConfirmPassword('');await supabase.auth.signOut();setSession(null);setNotice('Password changed. Sign in with your new password.');window.history.replaceState(null,'',window.location.pathname)}setBusy(false)}
