async function saveStockReceipt(e){e.preventDefault();setBusy(true);setError('');const f=receiptForm;const{error:err}=await supabase.rpc('hotel_receive_stock',{p_source:f.source,p_product:f.product,p_destination:f.destination,p_source_location:null,p_quantity:Number(f.quantity),p_unit_cost:Number(f.unit_cost),p_supplier:f.supplier,p_reference:f.reference});if(err)setError(err.message);else{setNotice('Stock receipt posted. Quantity added to destination inventory.');setReceiptForm(v=>({...v,quantity:'',unit_cost:'',reference:''}));await loadStocktaking()}setBusy(false)}
async function loadStocktaking(){const [l,s]=await Promise.all([supabase.rpc('hotel_stocktake_locations'),supabase.rpc('hotel_stocktake_list')]);if(l.error)setError(l.error.message);else setStockLocations(l.data||[]);if(s.error)setError(s.error.message);else setStockSessions(s.data||[])}
async function openStocktake(id){const{data,error:err}=await supabase.rpc('hotel_stocktake_detail',{p_id:id});if(err)setError(err.message);else{setStockDetail(data);setStockCounts({})}}
async function startStocktake(){setBusy(true);const{data,error:err}=await supabase.rpc('hotel_start_stocktake',{p_location:stockLocation});if(err)setError(err.message);else{await loadStocktaking();await openStocktake(data)}setBusy(false)}
async function saveStockCount(id){const value=stockCounts[id];if(value===undefined||value==='')return;const{error:err}=await supabase.rpc('hotel_stocktake_count',{p_line:id,p_quantity:Number(value)});if(err)setError(err.message);else if(stockDetail)setStockDetail(v=>({...v,lines:v.lines.map(x=>x.id===id?{...x,physical:Number(value)}:x)}))}
async function submitStocktake(){setBusy(true);const{error:err}=await supabase.rpc('hotel_stocktake_submit',{p_id:stockDetail.id});if(err)setError(err.message);else{await openStocktake(stockDetail.id);await loadStocktaking();setNotice('Stock count submitted for review')}setBusy(false)}
function printStockSheet(){if(!stockDetail){setError('Generate or open a stock sheet first.');return;}const headers=['No.','Item Name','Opening','Added','Total','Closing','Purchase Price/Unit','Selling Price','Amount (Sales)','Physical Count'];const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');const rows=stockDetail.lines.length?stockDetail.lines.map((x,i)=>'<tr>'+[i+1,x.name+' ('+(x.unit||'unit')+')',x.opening??x.system,x.added??0,x.total??x.system,x.system,x.purchase_price??'—',x.selling_price??'—',x.selling_price==null?'—':(Number(x.system)*Number(x.selling_price)).toFixed(2),'________________'].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="10">No stock items registered for this location. Register stock items and opening balances before physical counting.</td></tr>';const html='<!doctype html><html><head><meta charset="utf-8"><title>MWISHO Stock Sheet</title><style>@page{size:A4 landscape;margin:9mm}body{font-family:Arial,sans-serif;color:#17263a;margin:0}h1{text-align:center;font-size:18px;margin:0 0 4px}h2{text-align:center;font-size:13px;margin:0 0 12px}.meta{display:flex;justify-content:space-between;margin:10px 0 15px;font-size:11px}table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:9px}th,td{border:1px solid #444;padding:6px 3px;overflow-wrap:anywhere}th{background:#e7eefb}th:nth-child(2){width:18%}th:nth-child(7),th:nth-child(8),th:nth-child(10){width:10%}tr{break-inside:avoid}.foot{display:flex;justify-content:space-between;margin-top:25px;font-size:11px}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><h1>MWISHO MWISHO INVESTMENT</h1><h2>HOTEL STOCKTAKING SHEET — A4 LANDSCAPE</h2><div class="meta"><span>Location: '+esc(stockDetail.location)+'</span><span>Date: '+esc(new Date().toLocaleDateString('en-KE'))+'</span><span>Stock Taker: '+esc(access?.name||'')+'</span></div><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table><div class="foot"><span>Counted by: ___________________</span><span>Checked by: ___________________</span><span>Signature / Date: ___________________</span></div></body></html>';const w=window.open('','_blank');if(!w){setError('Allow pop-ups to print the stock sheet.');return;}w.document.open();w.document.write(html);w.document.close();w.onload=()=>w.print();}
function downloadStockVariance(){if(!stockDetail)return;const rows=[['No.','Item Name','System Closing','Physical Count','Variance'],...stockDetail.lines.map((x,i)=>[i+1,x.name,x.system,x.physical??'',x.physical==null?'':Number(x.physical)-Number(x.system)])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\\r\\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='MWISHO-stock-variance-'+stockDetail.id+'.csv';link.click();URL.revokeObjectURL(url)}
async function loadRequisitions(){const [a,b,p]=await Promise.all([supabase.rpc('my_requisition_sections'),supabase.rpc('my_department_requisitions'),supabase.rpc('my_requisition_permissions')]);if(!p.error)setReqPermissions(p.data||{departments:[],can_approve:false});if(a.error)setError(a.error.message);else setReqSections(a.data||[]);if(b.error)setError(b.error.message);else setRequisitions(b.data||[])}
async function submitRequisition(e){e.preventDefault();setBusy(true);setError('');const{error:err}=await supabase.rpc('submit_department_requisition',{p_department:reqDepartment,p_section:reqSection||null,p_purpose:reqPurpose,p_needed_on:null,p_items:reqItems});if(err)setError(err.message);else{setNotice('Requisition submitted');setReqPurpose('');setReqItems([{name:'',quantity:1,unit:'pcs'}]);await loadRequisitions()}setBusy(false)}
