 if(!supabase)return <div className="center"><div className="login"><h1>MWISHO POS</h1><p>Setup required: configure VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY on your hosting environment. Do not use a service-role key.</p></div></div>;
