 if(!session)return <div className="center"><form className="login" onSubmit={signIn}><h1>MWISHO</h1><p>Investment • Staff POS Login</p><label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="username"/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required autoComplete="current-password"/></label>{error&&<p role="alert" className="error">{error}</p>}{notice&&<p role="status">{notice}</p>}{resetEmailSent&&<p>If this account exists, check its inbox for the password reset link.</p>}<button className="primary" disabled={busy}>{busy?'Signing in…':'Sign in'}</button><button type="button" disabled={busy} onClick={requestPasswordReset}>Forgot password? Email reset link</button><small>Staff accounts are provisioned by authorized management.</small></form></div>;
